content = repo.read("logs/service.log")
lines = content.split("\n")
hits = []
for i, l in enumerate(lines):
    if "ALERT" in l:
        hits.append({
            "line_number": i + 1,
            "alert": l,
            "previous": lines[i - 1] if i > 0 else None,
            "following": lines[i + 1] if i + 1 < len(lines) else None,
        })
return {"total_lines": len(lines), "hits": hits, "full": content}
